struct tnode {
    struct tnode *left;
    char data;
    struct tnode *right;
};

struct tnode *nn(char x)
{
    struct tnode *t;
    t = malloc(sizeof(struct tnode));
    t->data = x;
    t->left = t->right = NULL;
    return t;
}

int nodes(struct tnode *t)
{
    if (t == NULL) return 0;
    return 1 + nodes(t->left)
             + nodes(t->right);
}

int leaves(struct tnode *t)
{
    if (t == NULL) return 0;
    if (!t->left && !t->right) return 1;
    return leaves(t->left)
         + leaves(t->right);
}

int height(struct tnode *t)  /* edges */
{
    int l, r;
    if (t == NULL) return -1;
    l = height(t->left);
    r = height(t->right);
    return 1 + (l > r ? l : r);
}

