struct tnode *del(struct tnode *t, int x)
{
    struct tnode *tmp;
    if (t == NULL) {
        printf("%d not found\n", x);
        return NULL;
    }
    if (x < t->data)
        t->left = del(t->left, x);
    else if (x > t->data)
        t->right = del(t->right, x);
    else if (t->left && t->right) {
        /* 2 children */
        tmp = t->right;
        while (tmp->left)
            /* successor */
            tmp = tmp->left;
        t->data = tmp->data;
        t->right = del(t->right,
                       tmp->data);
    /* 0 or 1 child */
    } else {
        tmp = t;
        t = t->left ? t->left : t->right;
        free(tmp);
    }
    return t;
}

