        t = x < t->data ? t->left
                        : t->right;
    return t != NULL;
}

struct tnode *del(struct tnode *t, int x)
{
    struct tnode *s;
    if (!t) return NULL;
    if (x < t->data)
        t->left = del(t->left, x);
    else if (x > t->data)
        t->right = del(t->right, x);
    else if (t->left && t->right) {
        for (s = t->right; s->left; )
            s = s->left;
        t->data = s->data;
        t->right = del(t->right, s->data);
    } else {
        s = t;
        t = t->left ? t->left : t->right;
        free(s);
    }
    return t;
}

