/* binary form: left = first child,
   right = next sibling              */
struct gnode {
    char data;
    struct gnode *child;
    struct gnode *sib;
};

struct gnode *nn(char x)
{
    struct gnode *t;
    t = malloc(sizeof(struct gnode));
    t->data = x;
    t->child = t->sib = NULL;
    return t;
}

void add(struct gnode *p, struct gnode *c)
{
    struct gnode *t = p->child;
    if (t == NULL) {
        p->child = c;
        return;
    }
    while (t->sib) t = t->sib;
    /* new right sibling */
    t->sib = c;
}

void show(struct gnode *t)
{
    if (t == NULL) return;
    printf("%c: left=%c right=%c\n",
           t->data,
           t->child ? t->child->data : '-',
           t->sib ? t->sib->data : '-');
    show(t->child);
    show(t->sib);
}

int main(void)
{
    struct gnode *A = nn('A');
    struct gnode *B = nn('B');
    struct gnode *D = nn('D');
    add(A, B); add(A, nn('C')); add(A, D);
    add(B, nn('E')); add(B, nn('F'));
    add(D, nn('G')); add(D, nn('H'));
    show(A);
    return 0;
}

