    int n, e, i, j, u, v, deg;

    scanf("%d %d", &n, &e);
    for (i = 0; i < e; i++) {
        scanf("%d %d", &u, &v);
        adj[u][v] = adj[v][u] = 1;
    }
    printf("Adjacency matrix:\n   ");
    for (j = 0; j < n; j++)
        printf("%c ", 'A' + j);
    printf("\n");
    for (i = 0; i < n; i++) {
        printf("%c: ", 'A' + i);
        for (j = 0; j < n; j++)
            printf("%d ", adj[i][j]);
        printf("\n");
    }
    for (i = 0; i < n; i++) {
        deg = 0;
        for (j = 0; j < n; j++)
            deg += adj[i][j];
        printf("Degree(%c) = %d\n",
               'A' + i, deg);
    }
    return 0;
}

